import { computed, onBeforeUnmount, onMounted, ref } from 'vue'

// The website's dark button's red fill (PixelButton.vue): 6px squares laid over an element, each with its own delay in
// and out, from the same seed as the website's, so the buttons feel like one product. It lays them again on resize.
const PX = 6

/** A seeded random source (mulberry32), the same as the website's, so every button scatters the same way. */
function rng(seed: number) {
  let s = seed >>> 0
  return () => {
    s = (s + 0x6D2B79F5) >>> 0
    let t = s
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export function usePixelGrid(el: () => HTMLElement | null) {
  const grid = ref<{ cols: number, w: number, h: number, cells: Array<Record<string, number>> } | null>(null)
  function lay() {
    const box = el()
    if (!box) return
    const rect = box.getBoundingClientRect()
    const w = rect.width - (box.offsetWidth - box.clientWidth)
    const h = rect.height - (box.offsetHeight - box.clientHeight)
    if (grid.value?.w === w && grid.value.h === h) return
    const cols = Math.ceil(w / PX)
    const rows = Math.ceil(h / PX)
    const rand = rng(29)
    grid.value = {
      cols,
      w,
      h,
      cells: Array.from({ length: cols * rows }, (_, k) => {
        // Eased along the button, so the front starts quick and settles.
        const e = 1 - (1 - (k % cols) / cols) ** 1.6
        return { '--i': Math.round(e * 60 + rand() * 20), '--o': Math.round(e * 50 + rand() * 20) }
      }),
    }
  }
  let ro: ResizeObserver | undefined
  onMounted(() => {
    lay()
    ro = new ResizeObserver(lay)
    const box = el()
    if (box) ro.observe(box)
  })
  onBeforeUnmount(() => ro?.disconnect())
  const style = computed(() => (grid.value ? { gridTemplateColumns: `repeat(${grid.value.cols}, ${PX}px)`, gridAutoRows: `${PX}px` } : undefined))
  return { grid, style }
}

'use client'
import { useRef, useState, type ReactNode } from 'react'
import { usePixelGrid } from '@/react/hooks/usePixelGrid'

// The website's button (home.css .btn-px, ButtonLink.vue): a square link, 36px with a 13px label (28px and 12px when
// small), whose hover is a fill of 6px squares coming in from the left with a little scatter and going out the same
// way; the label never changes size or weight. red is the flat red block (its squares come in black); secondary is
// outlined (its border turns red, the squares red); light and ghost are for a dark band. `pixels` is the dark main
// call to action (black, red squares); `arrow` adds the pixel arrow, lit and still. `grain` lays the footer's grain
// over the button. `fill="black"` brings the squares in black, for a light button on a red band. Where the label
// changes colour over the fill (secondary, light), each column of squares carries its own off-white copy of the label,
// so the label turns as the squares land and never fades through grey.
export type ButtonLinkVariant = 'red' | 'secondary' | 'light' | 'ghost'

export interface ButtonLinkProps {
  href: string
  variant?: ButtonLinkVariant
  size?: 'sm' | 'md'
  pixels?: boolean
  arrow?: boolean
  grain?: boolean
  fill?: 'black'
  className?: string
  children?: ReactNode
}

const PX = 6
// The arrow's lit cells on a 5 by 5 of dim ones, as [column, row]; each cell is 2px and a 1px gap.
const ARROW = [[2, 0], [3, 1], [0, 2], [1, 2], [2, 2], [3, 2], [4, 2], [3, 3], [2, 4]] as const
const CELL = 3

export function ButtonLink({ href, variant = 'red', size = 'md', pixels, arrow, grain, fill, className, children }: ButtonLinkProps) {
  const root = useRef<HTMLAnchorElement | null>(null)
  const { grid, style } = usePixelGrid(root)
  const tone = pixels ? 'dark' : variant
  const inks = !pixels && (variant === 'secondary' || variant === 'light')
  // The copies are made the first time the pointer or focus arrives, from the label's text.
  const [armed, setArmed] = useState(false)
  const [label, setLabel] = useState('')
  function arm() {
    if (armed || !inks) return
    setLabel(root.current?.querySelector(':scope > .ds-btnlink-label')?.textContent?.trim() ?? '')
    setArmed(true)
  }
  const inkCols = grid ? Array.from({ length: grid.cols }, (_, c) => ({ col: grid.cells[c]!, ink: { width: `${grid.w}px`, height: `${grid.h}px`, transform: `translateX(${-c * PX}px)` } })) : []
  return (
    <>
      <style href="ds-button-link" precedence="ds">{css}</style>
      <a
        data-ds="button-link"
        ref={root}
        href={href}
        className={className ? `ds-btnlink ${className}` : 'ds-btnlink'}
        data-variant={tone}
        data-size={size}
        data-grain={grain || undefined}
        data-arrow={arrow || undefined}
        data-fill={fill}
        onPointerEnter={arm}
        onPointerDown={arm}
        onFocus={arm}
      >
        {grid && (
          <span aria-hidden="true" className="ds-btnlink-fill" data-inks={inks || undefined} style={style}>
            {grid.cells.map((c, k) => <i key={k} style={c} />)}
          </span>
        )}
        {grid && inks && armed && (
          <span aria-hidden="true" className="ds-btnlink-inks" style={{ gridTemplateColumns: `repeat(${grid.cols}, ${PX}px)` }}>
            {inkCols.map((c, k) => <i key={k} style={c.col}><span className="ds-btnlink-ink" style={c.ink}><span className="ds-btnlink-label">{label}</span></span></i>)}
          </span>
        )}
        <span className="ds-btnlink-label">{children}</span>
        {arrow && (
          <svg aria-hidden="true" className="ds-btnlink-arrow" viewBox={`0 0 ${5 * CELL - 1} ${5 * CELL - 1}`} width="11" height="11">
            <g className="ds-btnlink-arrow-dim">
              {[1, 2, 3, 4, 5].map(c => [1, 2, 3, 4, 5].map(r => <rect key={`${c}-${r}`} x={(c - 1) * CELL} y={(r - 1) * CELL} width={CELL - 1} height={CELL - 1} />))}
            </g>
            <g className="ds-btnlink-arrow-lit">
              {ARROW.map(([c, r]) => <rect key={`${c}${r}`} x={c * CELL} y={r * CELL} width={CELL - 1} height={CELL - 1} />)}
            </g>
          </svg>
        )}
      </a>
    </>
  )
}

export default ButtonLink

