          }),
        }
      })
    }
    lay()
    const ro = new ResizeObserver(lay)
    ro.observe(box)
    return () => ro.disconnect()
  }, [el])
  const style: CSSProperties | undefined = grid ? { gridTemplateColumns: `repeat(${grid.cols}, ${PX}px)`, gridAutoRows: `${PX}px` } : undefined
  return { grid, style }
}

